$id=str_repeat('a',64);$base=['key'=>'single:kpop-original:01','orderKey'=>$id,'kind'=>'single','title'=>'원본','genre'=>'kpop-original','ep'=>'1','video'=>'','audio'=>'/verified-upload.mp3','visibility'=>'private'];
