$video=['key'=>'ZYXWVUTSRQP','orderKey'=>$id,'kind'=>'video','video'=>'ZYXWVUTSRQP','title'=>'YouTube'];ie_check(nie_project($edits,[$video])[0]['title']===$projected['title'],'same canonical title in YouTube and Music');
$fallback=nie_song_id('youtube:ZYXWVUTSRQP');$edits[nie_meta_key('song',$fallback)]=['fields'=>['title'=>'미연결 영상']];ie_check(nie_fields($edits,['key'=>'ZYXWVUTSRQP','video'=>'ZYXWVUTSRQP'])['title']==='미연결 영상','mixed-case video ID resolves to safe metadata key');
$actKey=nie_meta_key('act','kpop-original:1');$edits[$actKey]=['fields'=>['title'=>'첫 이야기','description'=>'ACT 설명']];$edits[nie_meta_key('act','kpop-original:9')]=['fields'=>['title'=>'다른 ACT']];$labels=nie_act_labels($edits,[$base]);ie_check($labels===['kpop-original:1'=>'첫 이야기'],'only current page ACT identities are exposed');$collection=nie_project($edits,[['key'=>'playlist:kpop-original:act-1','kind'=>'playlist','genre'=>'kpop-original','act'=>'1','title'=>'ACT 1']])[0];ie_check($collection['title']==='첫 이야기','collection and ACT title use same metadata');ie_check(strlen(nie_meta_key('song',nie_song_id(str_repeat('z',190))))<=191,'all source identities fit the audited bridge key');
echo "INLINE_EDIT_SHARED_PROJECTION_MEDIA_PRIVACY_AND_ACT_OK\n";
